(6011889, 880470, 49520, '<td valign="top">Composition too centered for my taste... Especially since looking to his left.</td>', 'Composition too centered for my taste... Especially since looking to his left.', '2010-05-17 21:39:00.000000', NULL, 1),
(6011900, 880199, 49520, '<td valign="top">A bit heavy on the right side in terms of composition... Other than that, I love the exposure and softness.</td>', 'A bit heavy on the right side in terms of composition... Other than that, I love the exposure and softness.', '2010-05-17 21:47:36.000000', NULL, 1),
(6011901, 880060, 20957, '<td valign="top">if only the camera were actually in the shot :)  I missed it at first..Maybe getting in a bit tighter would have made the expression, looking a bit uncomfortable on the other side of the lens, more evocative?</td>', 'if only the camera were actually in the shot :)  I missed it at first..Maybe getting in a bit tighter would have made the expression, looking a bit uncomfortable on the other side of the lens, more evocative?', '2010-05-17 21:48:11.000000', NULL, 1),
(6011908, 879810, 20957, '<td valign="top">Good composition for a portrait, good use of focal length.  The sharpness of the photo is a bit too much for my tastes... was it a high iso or done in post process?</td>', 'Good composition for a portrait, good use of focal length.  The sharpness of the photo is a bit too much for my tastes... was it a high iso or done in post process?', '2010-05-17 21:49:16.000000', NULL, 1),
(6011909, 879098, 20957, '<td valign="top">great comp.. emotive and excellent exposure...</td>', 'great comp.. emotive and excellent exposure...', '2010-05-17 21:49:40.000000', NULL, 1),
(6011911, 879427, 20957, '<td valign="top">no self portraits??? :)  Great softness to the skin while maintaining sharpness in eyes.. position of the hand takes away from the shot a little in my mind... perhaps it could have just been a finger pulling down the blinds for a peek through?  the hand and wrist are too solid for me..</td>', 'no self portraits??? :)  Great softness to the skin while maintaining sharpness in eyes.. position of the hand takes away from the shot a little in my mind... perhaps it could have just been a finger pulling down the blinds for a peek through?  the hand and wrist are too solid for me..', '2010-05-17 21:51:13.000000', NULL, 1),
(6011915, 880413, 20957, '<td valign="top">nice composition, expression and exposure.  very interesting subject.</td>', 'nice composition, expression and exposure.  very interesting subject.', '2010-05-17 21:53:24.000000', NULL, 1),
(6011918, 880199, 20957, '<td valign="top">great composition, i like the focal length.  only problem for me is exposure..its good on the hair and lips are spot on.. cheeks are almost blinding :)</td>', 'great composition, i like the focal length.  only problem for me is exposure..its good on the hair and lips are spot on.. cheeks are almost blinding :)', '2010-05-17 21:54:43.000000', NULL, 1),
(6011919, 879865, 20957, '<td valign="top">great use of props.. a little light behind the book and left side of hair would be nice as they melt into the background...</td>', 'great use of props.. a little light behind the book and left side of hair would be nice as they melt into the background...', '2010-05-17 21:55:31.000000', NULL, 1),
(6011920, 880267, 20957, '<td valign="top">great shot... you nailed the DOF, lots of people hit it on the nose and loose the eyes, this spot on..</td>', 'great shot... you nailed the DOF, lots of people hit it on the nose and loose the eyes, this spot on..', '2010-05-17 21:56:21.000000', NULL, 1),
(6011994, 880098, 108990, '<td valign="top">Cool!</td>', 'Cool!', '2010-05-17 22:32:51.000000', NULL, 1),
