(6012030, 880264, 20957, '<td valign="top">Great use of lighting techniques. Would love to see those eyes</td>', 'Great use of lighting techniques. Would love to see those eyes', '2010-05-17 22:47:42.000000', NULL, 1),
(6012033, 880501, 20957, '<td valign="top">Tint is distracting and poor in execution. Image is composed well and interesting. Would have left it as is.</td>', 'Tint is distracting and poor in execution. Image is composed well and interesting. Would have left it as is.', '2010-05-17 22:48:51.000000', NULL, 1),
(6012035, 880424, 20957, '<td valign="top">Playing with the crop makes this one more interesting as the neck line is just taking up space. Play with it!!!!</td>', 'Playing with the crop makes this one more interesting as the neck line is just taking up space. Play with it!!!!', '2010-05-17 22:50:14.000000', NULL, 1),
(6012038, 879203, 20957, '<td valign="top">Excellent!  Interesting subject, great expression and crop is great too. Well done</td>', 'Excellent!  Interesting subject, great expression and crop is great too. Well done', '2010-05-17 22:51:12.000000', NULL, 1),
(6012041, 880136, 20957, '<td valign="top">Needs more smoke!!</td>', 'Needs more smoke!!', '2010-05-17 22:51:43.000000', NULL, 1),
